import java.util.*;
import java.io.*;

public class LetsDoVariant5 {
    public static void main(String[] args) throws IOException {
        DataInputStream dis = new DataInputStream(System.in);
        int n = readInt(dis);
        int b = readInt(dis);
        int[] array = new int[n];
        for (int i = 0; i < n; i++) {
            array[i] = readInt(dis);
        }
        int[] prefixEven = new int[n];
        int[] prefixOdd = new int[n];
        int countEven = 0, countOdd = 0;
        for (int i = 0; i < n; i++) {
            if (array[i] % 2 == 0) countEven++;
            else countOdd++;
            prefixEven[i] = countEven;
            prefixOdd[i] = countOdd;
        }
        List<Integer> diffList = new ArrayList<>();
        int lastIdx = 0;
        for (int i = 1; i < n - 2; i += 2) {
            int x, y;
            if (lastIdx == 0) {
                x = prefixEven[i];
                y = prefixOdd[i];
            } else {
                x = prefixEven[i] - prefixEven[lastIdx];
                y = prefixOdd[i] - prefixOdd[lastIdx];
            }
            if (x == y) {
                diffList.add(Math.abs(array[i + 1] - array[i]));
                lastIdx = i;
            }
        }
        int p = diffList.size();
        int[] arr = new int[p];
        for (int i = 0; i < p; i++) {
            arr[i] = diffList.get(i);
        }
        int[] val = new int[p];
        Arrays.fill(val, 1);
        int[][] dpArr = new int[p + 1][b + 1];
        for (int i = 0; i <= p; i++) {
            for (int w = 0; w <= b; w++) {
                if (i == 0 || w == 0) {
                    dpArr[i][w] = 0;
                } else if (arr[i - 1] <= w) {
                    dpArr[i][w] = Math.max(val[i - 1] + dpArr[i - 1][w - arr[i - 1]], dpArr[i - 1][w]);
                } else {
                    dpArr[i][w] = dpArr[i - 1][w];
                }
            }
        }
        System.out.println(dpArr[p][b]);
        dis.close();
    }
    static int readInt(DataInputStream dis) throws IOException {
        int ret = 0;
        int c;
        while ((c = dis.read()) != -1 && c <= ' ') ;
        do {
            ret = ret * 10 + (c - '0');
        } while ((c = dis.read()) != -1 && c >= '0' && c <= '9');
        return ret;
    }
}
